namespace sv_3f3143e7312b434a9e82e4ce939a7913.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and latest alert count, notifying all subscribed components on change.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";
    private int _lowStockCount;

    public string SelectedWarehouseId => _selectedWarehouseId;
    public int LowStockCount => _lowStockCount;

    public event Action? OnWarehouseChanged;
    public event Action? OnAlertCountChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A – Downtown"),
        ("WH-002", "Warehouse B – Airport"),
        ("WH-003", "Warehouse C – Harbor"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        _lowStockCount = 0; // reset until next poll
        OnWarehouseChanged?.Invoke();
        OnAlertCountChanged?.Invoke();
    }

    public void UpdateAlertCount(int count)
    {
        _lowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

namespace sv_3f3143e7312b434a9e82e4ce939a7913.Services;

/// <summary>
/// Simulates a database query for low-stock items in a warehouse.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService State
@implements IDisposable

<select class="form-select form-select-sm" style="max-width: 260px;"
        value="@State.SelectedWarehouseId"
        @onchange="OnSelectionChanged">
    @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnSelectionChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            State.SetWarehouse(id);
        }
    }

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += StateHasChanged;
    }

    public void Dispose()
    {
        State.OnWarehouseChanged -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService State
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@State.LowStockCount</span>

@code {
    private string BadgeClass => State.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += OnStateChanged;
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnAlertCountChanged -= OnStateChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService State
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Warehouse: <strong>@CurrentWarehouseName</strong>
        </p>
        <p class="card-text">
            Items below minimum level:
            <span class="badge @BadgeClass fs-5">@State.LowStockCount</span>
        </p>
        <p class="text-muted small mb-0">
            @if (_lastChecked is not null)
            {
                <span>Last checked: @_lastChecked.Value.ToString("HH:mm:ss")</span>
            }
            else
            {
                <span>Polling starting…</span>
            }
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;

    private string CurrentWarehouseName =>
        Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == State.SelectedWarehouseId).Name
        ?? State.SelectedWarehouseId;

    private string BadgeClass => State.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            // Initial fetch then poll every 10 seconds
            await PollAlerts();
            _ = StartPollingLoop(_cts.Token);
        }
    }

    private async Task StartPollingLoop(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollAlerts();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(State.SelectedWarehouseId);
        _lastChecked = DateTime.Now;
        // This pushes the update to ALL subscribers via the shared service
        State.UpdateAlertCount(count);
    }

    private void OnWarehouseChanged()
    {
        // Re-poll immediately when warehouse changes
        InvokeAsync(async () =>
        {
            await PollAlerts();
            StateHasChanged();
        });
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

